#!ibl edition=2
$n = [limbs:browser]{op:"navigate", url:"http://127.0.0.1:8979/board", wait:"load"}
$s = [limbs:browser]{op:"snapshot"}
$roles = unique(map($s.snapshot, ($e)=>$e.role))
$regions = $s.snapshot >> [table:filter]{where:($e)=>$e.role=="region" or $e.role=="heading"}
$card = ($s.snapshot >> [table:filter]{where:($e)=>contains($e.name,"W-1004")})
$today = ($s.snapshot >> [table:filter]{where:($e)=>contains($e.name,"오늘 처리")})
$d = [try] { [limbs:browser]{op:"drag", source_ref:$card[0].ref, target_ref:$today[0].ref} } [catch] { {failed:true, code:$error.code, message:$error.message} }
$e = [limbs:browser]{op:"evaluate", expression:"Array.from(document.querySelectorAll('.col')).map(c=>c.dataset.col+':'+c.querySelectorAll('.card').length).join(' ')"}
return {count:$s.element_count, shown:$s.shown_count, roles:$roles, regions:$regions, card:$card, today:$today, drag:$d, after:$e.result}
